This class is a custom `LayerDrawable` in Android that stacks multiple drawables (icons) on top of each other, scaling them down by a specified factor (`iconScale`). It also positions the icons in the center of the bounds with a small inset to avoid overlapping.

In Swift, you can create a similar class using `CALayer` and `UIImage` instead of `LayerDrawable` and `Drawable`. Here's a rough equivalent:

```swift
import UIKit

class StackedLayers: CALayer {
    private var layers: [CALayer] = []
    private let iconScale: CGFloat = 0.7
    private var shouldPlaceIcons = true

    init(layers: [UIImage]) {
        super.init()
        self.layers = layers.map { CALayer() }
        for (index, layer) in layers.enumerated() {
            layer.contents = layer.cgImage
            addSublayer(layer)
        }
    }

    override func layoutSublayers() {
        super.layoutSublayers()
        if shouldPlaceIcons {
            placeIcons()
        } else {
            shouldPlaceIcons = true
        }
    }

    private func placeIcons() {
        shouldPlaceIcons = false
        let newWidth = bounds.width
        let iconsSize = floor(newWidth * iconScale)
        let iconsInset = (newWidth - iconsSize) - 1

        for (index, layer) in layers.enumerated() {
            layer.bounds = CGRect(x: 0, y: 0, width: iconsSize, height: iconsSize)
            layer.position = CGPoint(x: bounds.midX, y: bounds.midY)
            if index == 1 {
                layer.frame = CGRect(x: iconsInset, y: 0, width: bounds.width - (2 * iconsInset), height: bounds.height)
            } else if index == 0 {
                layer.frame = CGRect(x: 0, y: iconsInset, width: bounds.width - (2 * iconsInset), height: bounds.height)
            }
        }
    }
}
```

