const XLSX = require('xlsx');
const _ = require('lodash');

function compareExcelFiles(file1, file2, callback) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet_name_list1 = workbook1.SheetNames;
  const sheet_name_list2 = workbook2.SheetNames;

  let differences = [];

  // Compare each sheet name by name
  const commonSheets = _.intersection(sheet_name_list1, sheet_name_list2);
  commonSheets.forEach(sheetName => {
    const worksheet1 = workbook1.Sheets[sheetName];
    const worksheet2 = workbook2.Sheets[sheetName];

    const data1 = _.map(XLSX.utils.sheet_to_json(worksheet1), row => _.values(row));
    const data2 = _.map(XLSX.utils.sheet_to_json(worksheet2), row => _.values(row));

    const differencesInRow = _.differenceWith(data1, data2, _.isEqual);
    differences = differences.concat(differencesInRow);
  });

  // Compare each sheet name by name if it's not in common sheets
  const uniqueSheets1 = _.difference(sheet_name_list1, commonSheets);
  uniqueSheets1.forEach(sheetName => {
    const worksheet1 = workbook1.Sheets[sheetName];
    differences.push(`Sheet "${sheetName}" from file1 not found in file2.`);
  });

  const uniqueSheets2 = _.difference(sheet_name_list2, commonSheets);
  uniqueSheets2.forEach(sheetName => {
    const worksheet2 = workbook2.Sheets[sheetName];
    differences.push(`Sheet "${sheetName}" from file2 not found in file1.`);
  });

  callback(differences);
}

// Usage
compareExcelFiles('file1.xlsx', 'file2.xlsx', (differences) => {
  console.log(differences);
});
